                        style.createdDate.as("createdDate")
                ))
                .from(style)
                .leftJoin(style.profile, profile)
                .where(style.id.eq(styleId))
                .fetchOne();

        // 4. 미디어 URL과 상품 정보를 DTO에 주입
        if (styleDetail != null) {
            styleDetail.setMediaUrls(mediaUrls);

